import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"研究日志与纪律","description":"","frontmatter":{"title":"研究日志与纪律","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/research-log-discipline.md","filePath":"quant/research-log-discipline.md","lastUpdated":1789023840000}'),c={name:"quant/research-log-discipline.md"};function p(u,a,B,f,_,m){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="研究日志与纪律" tabindex="-1">研究日志与纪律 <a class="header-anchor" href="#研究日志与纪律" aria-label="Permalink to &quot;研究日志与纪律&quot;">​</a></h1><div class="epigraph"><p>每次试错都是一次假设检验。不记账的试错让显著性在实验室里被用尽，样本外只剩被选中的那条曲线。</p><footer>—— Harvey, Liu and Zhu, … and the Cross-Section of Expected Returns, RFS, 2016；Bailey, Borodin, López de Prado and Zhu, The Probability of Backtest Overfitting, 以及 CSCV 方法；McLean and Pontiff, JF, 2016</footer></div><p><a href="/quant/backtest-vectorization">上一课</a>选定引擎。<a href="/quant/feature-store-research">特征商店</a>已要求实验元数据。本课的缺口是<strong>人的试错过程</strong>：Harvey、Liu 与 Zhu（2016）指出多重检验下多数「因子」过不了更高的 t 阈值；Bailey 等把回测过拟合概率写成可计算对象；McLean 与 Pontiff（2016）记录发表后衰减。后课生产监控处理上线之后；本课处理上线之前的实验室账本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>研究员改参数、换宇宙、换清洗、加一个过滤器，直到曲线好看。若不记录尝试次数与失败，报告里的 t 统计量对应的是被选择的极值，而不是预先登记的假设。问题是把研究当临床试验：预先登记问题、允许的数据范围、主要指标；偏离必须另开实验号，不能覆盖。特征版本与代码哈希是必要但不充分——还要记「这是第几次尝试同一故事」。</p><p>发表偏差在实验室内部同样存在：只有正结果被写进备忘录。日志应包含负结果与「因泄漏作废」的实验，否则团队会重复踩同一块未来函数。McLean–Pontiff 的样本外衰减有一部分来自数据开采与费用；内部日志是降低自己开采强度的工具。</p><h3 id="主要指标必须预先锁死" tabindex="-1">主要指标必须预先锁死 <a class="header-anchor" href="#主要指标必须预先锁死" aria-label="Permalink to &quot;主要指标必须预先锁死&quot;">​</a></h3><p>若主指标可以在夏普、Calmar、换手调整后收益、特定子期之间切换，多重检验没有上界。登记：样本外切分点、成本模型版本、是否允许在危机子期上「解释掉」。子期分析是探索，不能回头改主指标。与<a href="/quant/backtest-overfitting">过拟合</a>课的 CSCV 结合：日志提供尝试次数的下限，CSCV 提供过拟合概率的估计。</p><p><span class="marginnote">纪律不是反对探索。探索放在沙盒宇宙，结果标为 exploratory，不得直接进生产候选。生产候选必须来自登记实验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条实验记录：假设陈述、特征版本、宇宙、引擎类型、成本、尝试序号、主指标、是否泄漏作废、结论。存储与代码仓库挂钩。周会审查的是日志完整性，不只是曲线。复制：另一人仅凭日志能复现数字；不能复现则实验无效。</p><p>与数据商对照、黄金样本失败，应自动作废依赖该字段的实验，而不是手动挑一个「看起来没坏」的子期。变更管理与<a href="/quant/exchange-outages">交易所故障</a>里 Knight 的教训同构：配置漂移要留痕。</p><h3 id="中国样本的额外登记项" tabindex="-1">中国样本的额外登记项 <a class="header-anchor" href="#中国样本的额外登记项" aria-label="Permalink to &quot;中国样本的额外登记项&quot;">​</a></h3><p>制度分段：涨跌停比例、注册制、程序化规则、融券政策，必须以生效日写入实验，禁止用现行规则回填全样本。否则「全 A 十年夏普」是一个从未存在的市场。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多重检验把噪声的尾部变成「发现」。记账不能消灭噪声，但能阻止把尾部当唯一叙事，并为更高阈值提供尝试次数输入。Harvey–Liu–Zhu 的建议阈值随尝试次数上升；没有日志就没有分母，阈值无法校准，默认应更保守。</p><p>衰减：即使诚实，拥挤与费用也会降低样本外。日志把「我们内部已经衰减」与「市场拥挤」分开：前者看登记后的第一次样本外；后者看实盘后课容量。</p>',17)),(e(),s(E,null,{default:r(()=>[h(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Reg%5B%22%E9%A2%84%E5%85%88%E7%99%BB%E8%AE%B0%20%E4%B8%BB%E6%8C%87%E6%A0%87%E4%B8%8E%E5%88%87%E5%88%86%22%5D%20--%3E%20Run%5B%22%E5%AE%9E%E9%AA%8C%22%5D%0A%20%20Run%20--%3E%20Log%5B%22%E5%B0%9D%E8%AF%95%E5%BA%8F%E5%8F%B7%20%E7%89%88%E6%9C%AC%20%E8%B4%9F%E7%BB%93%E6%9E%9C%22%5D%0A%20%20Log%20--%3E%20CSCV%5B%22%E8%BF%87%E6%8B%9F%E5%90%88%E8%AF%8A%E6%96%AD%22%5D%0A%20%20Log%20--%3E%20Cand%5B%22%E7%94%9F%E4%BA%A7%E5%80%99%E9%80%89%22%5D%0A%20%20Expl%5B%22%E6%B2%99%E7%9B%92%E6%8E%A2%E7%B4%A2%22%5D%20--%3E%7C%22%E4%B8%8D%E5%BE%97%E7%9B%B4%E6%8E%A5%E8%BF%9B%22%7C%20Cand%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何把日志做得很完整以通过合规检查、同时仍隐藏尝试。隐瞒尝试次数属于研究不端。个人隐私与未公开持仓不要写进可外发的日志。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>试错次数是检验的分母；无日志则 t 值不可信。</li><li>主指标预先锁定；探索与生产候选分轨。</li><li>制度生效日必须登记，禁止现行规则回填历史。</li><li>出处：Harvey, Liu and Zhu, <em>RFS</em>, 2016；McLean and Pontiff, <em>JF</em>, 2016；Bailey 等 CSCV。</li></ul>',4))])}const q=o(c,[["render",p]]);export{C as __pageData,q as default};
